$( Typecodes of a Peano-style database: wff, term and var give the letters W, T and V. $)
$c ( ) -> = wff term var |- 0 $.
$( $j syntax 'wff'; syntax 'term'; syntax 'var'; syntax '|-' as 'wff'; $)
$v ph x t $.
wph $f wff ph $.
vx $f var x $.
tt $f term t $.
tx $a term x $.
t0 $a term 0 $.
weq $a wff ( x = x ) $.
